mapper.sql:
SELECT ROW_NUMBER() OVER(ORDER BY A.REG_DTTM DESC) AS LINE_NO , COUNT(*) OVER() AS TOTAL_CNT , A.SBJCT_ID , A.CRCLMN_NO AS SBJCT_CD , A.PROF_ID , A.SBJCTNM , A.SMSTR_CHRT_ID , A.SBJCT_YR , A.SBJCT_SMSTR , A.CRS_GBNCD , A.SBJCT_TYCD , A.LCTR_GBNCD , A.CMCRS_GBNCD , A.EVL_GBNCD , A.DVCLAS_NO , A.CRDTS , A.USEYN , A.ATNDLC_CERT_STSCD , A.REG_DTTM , ORG.ORGNM , CRS_GBNCD_CD.CDNM AS CRS_GBNCDNM , SBJCT_TYCD_CD.CDNM AS SBJCT_TYCDNM , LCTR_GBNCD_CD.CDNM AS LCTR_GBNCDNM , CMCRS_GBNCD_CD.CDNM AS CMCRS_GBNCDNM , EVL_GBNCD_CD.CDNM AS EVL_GBNCDNM , NVL(ADM.PROF_USERNM, '-') AS PROF_USERNM , NVL(ADM.TUT_USERNM, '-') AS TUT_USERNM , NVL(ATNDLC.ATNDLC_CNT, 0) AS ATNDLC_CNT , NVL(ATNDLC.AUDIT_CNT, 0) AS AUDIT_CNT FROM TB_LMS_SBJCT A INNER JOIN TB_LMS_SMSTR_CHRT B ON B.SMSTR_CHRT_ID = A.SMSTR_CHRT_ID LEFT JOIN TB_LMS_ORG ORG ON ORG.ORG_ID = B.ORG_ID LEFT JOIN TB_LMS_CMMN_CD CRS_GBNCD_CD ON CRS_GBNCD_CD.LANG_CD = NVL(#{langCd}, 'ko') AND CRS_GBNCD_CD.UP_CD = 'CRS_GBNCD' AND CRS_GBNCD_CD.CD = A.CRS_GBNCD LEFT JOIN TB_LMS_CMMN_CD SBJCT_TYCD_CD ON SBJCT_TYCD_CD.LANG_CD = NVL(#{langCd}, 'ko') AND SBJCT_TYCD_CD.UP_CD = 'SBJCT_TYCD' AND SBJCT_TYCD_CD.CD = A.SBJCT_TYCD LEFT JOIN TB_LMS_CMMN_CD LCTR_GBNCD_CD ON LCTR_GBNCD_CD.LANG_CD = NVL(#{langCd}, 'ko') AND LCTR_GBNCD_CD.UP_CD = 'LCTR_GBNCD' AND LCTR_GBNCD_CD.CD = A.LCTR_GBNCD LEFT JOIN TB_LMS_CMMN_CD CMCRS_GBNCD_CD ON CMCRS_GBNCD_CD.LANG_CD = NVL(#{langCd}, 'ko') AND CMCRS_GBNCD_CD.UP_CD = 'CMCRS_GBNCD' AND CMCRS_GBNCD_CD.CD = A.CMCRS_GBNCD LEFT JOIN TB_LMS_CMMN_CD EVL_GBNCD_CD ON EVL_GBNCD_CD.LANG_CD = NVL(#{langCd}, 'ko') AND EVL_GBNCD_CD.UP_CD = 'EVL_GBNCD' AND EVL_GBNCD_CD.CD = A.EVL_GBNCD LEFT JOIN ( SELECT T1.SBJCT_ID , MAX(CASE WHEN T1.SBJCT_ADM_TYCD = 'PROF' THEN T2.USERNM END) AS PROF_USERNM , MAX(CASE WHEN T1.SBJCT_ADM_TYCD = 'TUT' THEN T2.USERNM END) AS TUT_USERNM FROM TB_LMS_SBJCT_ADM T1 JOIN TB_LMS_USER T2 ON T2.USER_ID = T1.USER_ID GROUP BY T1.SBJCT_ID ) ADM ON ADM.SBJCT_ID = A.SBJCT_ID LEFT JOIN ( SELECT SBJCT_ID , SUM(CASE WHEN ATNDLC_STSCD = 'APPROVE' AND NVL(AUDITYN, 'N') = 'N' THEN 1 ELSE 0 END) AS ATNDLC_CNT , SUM(CASE WHEN ATNDLC_STSCD = 'APPROVE' AND AUDITYN = 'Y' THEN 1 ELSE 0 END) AS AUDIT_CNT FROM TB_LMS_ATNDLC GROUP BY SBJCT_ID ) ATNDLC ON ATNDLC.SBJCT_ID = A.SBJCT_ID WHERE 1 = 1 AND A.DELYN = 'N' AND B.ORG_ID = #{orgId} AND NVL(A.CRS_GBNCD, ' ') != 'OPEN_CRS' AND NVL(A.SBJCT_TYCD, ' ') != 'OPEN_LCTR_SYSTEM'
AND A.SMSTR_CHRT_ID = #{smstrChrtId}
AND A.SBJCT_YR = #{sbjctYr}
AND TRIM(A.SBJCT_SMSTR) = #{sbjctSmstr}
AND A.CRS_GBNCD = #{crsGbncd}
AND A.SBJCT_TYCD = #{sbjctTycd}
AND A.SBJCTNM LIKE FN_LIKE_VAL(#{searchValue})
ORDER BY A.REG_DTTM DESC

mapper.select:
/* SQL ID : SbjctDAO.list 설 명 : 과목 조회 */ SELECT SBJCT_ID , SBJCTNM FROM TB_LMS_SBJCT TLCC WHERE USEYN = 'Y' AND DELYN = 'N'
AND SBJCT_ID = #{haksaYear}
AND CRS_ID = #{haksaTerm}

mapper.sql:
SELECT ROW_NUMBER() OVER(ORDER BY A.REG_DTTM DESC) AS LINE_NO , COUNT(*) OVER() AS TOTAL_CNT , A.SBJCT_ID , A.CRCLMN_NO AS SBJCT_CD , A.PROF_ID , A.SBJCTNM , A.SMSTR_CHRT_ID , A.SBJCT_YR , A.SBJCT_SMSTR , A.CRS_GBNCD , A.SBJCT_TYCD , A.LCTR_GBNCD , A.USEYN , A.SBJCT_LCTR_SDTTM , A.SBJCT_LCTR_EDTTM , A.REG_DTTM , ORG.ORGNM , CRS_GBNCD_CD.CDNM AS CRS_GBNCDNM , SBJCT_TYCD_CD.CDNM AS SBJCT_TYCDNM , LCTR_GBNCD_CD.CDNM AS LCTR_GBNCDNM , NVL(ADM.PROF_USERNM, '-') AS PROF_USERNM /* 공개강좌 목록의 미리보기 버튼에서 사용할 콘텐츠 URL을 조회한다. */ , ( SELECT MAX(C.CONTS_URL) FROM TB_LMS_LCTR_WKNO_SCHDL W JOIN TB_LMS_LCTR L ON L.LCTR_WKNO_SCHDL_ID = W.LCTR_WKNO_SCHDL_ID AND NVL(L.DELYN, 'N') = 'N' JOIN TB_LMS_LCTR_CONTS C ON C.LCTR_ID = L.LCTR_ID WHERE W.SBJCT_ID = A.SBJCT_ID AND NVL(W.DELYN, 'N') = 'N' AND C.CONTS_URL IS NOT NULL ) AS LESSON_CNTS_URL FROM TB_LMS_SBJCT A INNER JOIN TB_LMS_SMSTR_CHRT B ON B.SMSTR_CHRT_ID = A.SMSTR_CHRT_ID LEFT JOIN TB_LMS_ORG ORG ON ORG.ORG_ID = B.ORG_ID LEFT JOIN TB_LMS_CMMN_CD CRS_GBNCD_CD ON CRS_GBNCD_CD.LANG_CD = NVL(#{langCd}, 'ko') AND CRS_GBNCD_CD.UP_CD = 'CRS_GBNCD' AND CRS_GBNCD_CD.CD = A.CRS_GBNCD LEFT JOIN TB_LMS_CMMN_CD SBJCT_TYCD_CD ON SBJCT_TYCD_CD.LANG_CD = NVL(#{langCd}, 'ko') AND SBJCT_TYCD_CD.UP_CD = 'SBJCT_TYCD' AND SBJCT_TYCD_CD.CD = A.SBJCT_TYCD LEFT JOIN TB_LMS_CMMN_CD LCTR_GBNCD_CD ON LCTR_GBNCD_CD.LANG_CD = NVL(#{langCd}, 'ko') AND LCTR_GBNCD_CD.UP_CD = 'LCTR_GBNCD' AND LCTR_GBNCD_CD.CD = A.LCTR_GBNCD LEFT JOIN ( SELECT T1.SBJCT_ID , MAX(CASE WHEN T1.SBJCT_ADM_TYCD = 'PROF' THEN T2.USERNM END) AS PROF_USERNM FROM TB_LMS_SBJCT_ADM T1 JOIN TB_LMS_USER T2 ON T2.USER_ID = T1.USER_ID GROUP BY T1.SBJCT_ID ) ADM ON ADM.SBJCT_ID = A.SBJCT_ID WHERE A.DELYN = 'N' AND B.ORG_ID = #{orgId} /* 공개강좌개설 목록은 과목개설 데이터 중 공개강좌 시스템 유형만 조회한다. */ AND A.CRS_GBNCD = 'OPEN_CRS' AND A.SBJCT_TYCD = 'OPEN_LCTR_SYSTEM'
AND A.SMSTR_CHRT_ID = #{smstrChrtId}
AND A.SBJCT_YR = #{sbjctYr}
AND TRIM(A.SBJCT_SMSTR) = #{sbjctSmstr}
AND A.CRS_GBNCD = #{crsGbncd}
AND A.LCTR_GBNCD = #{lctrGbncd}
AND A.SBJCTNM LIKE FN_LIKE_VAL(#{searchValue})
ORDER BY A.REG_DTTM DESC

mapper.select:
/* SQL ID : SbjctDAO.selectSbjctOfringSchdlList 설 명 : 과목개설 주차 기간 설정 목록 조회 */ SELECT * FROM ( SELECT S.SBJCT_SCHDL_ID , A.SBJCT_ID , S.SMSTR_CHRT_SCHDL_ID , S.SBJCT_SCHDL_WKNO , S.TOC_SEQNO , S.SBJCT_SYMD , S.SBJCT_EYMD , S.SBJCT_ATNDC_RCG_SYMD , S.SBJCT_ATNDC_RCG_EYMD , S.RGTR_ID , S.REG_DTTM , S.MDFR_ID , S.MOD_DTTM , S.SBJCT_SCHDL_WKNONM FROM TB_LMS_SBJCT A INNER JOIN TB_LMS_SMSTR_CHRT B ON B.SMSTR_CHRT_ID = A.SMSTR_CHRT_ID INNER JOIN TB_LMS_SBJCT_SCHDL S ON S.SBJCT_ID = A.SBJCT_ID WHERE A.SBJCT_ID = #{sbjctId} AND A.DELYN = 'N'
AND B.ORG_ID = #{orgId}
UNION ALL SELECT CAST(NULL AS VARCHAR2(30)) AS SBJCT_SCHDL_ID , A.SBJCT_ID , C.SMSTR_CHRT_SCHDL_ID , C.SCHDL_WKNO AS SBJCT_SCHDL_WKNO , C.TOC_SEQNO , C.SMSTR_CHRT_SYMD AS SBJCT_SYMD , C.SMSTR_CHRT_EYMD AS SBJCT_EYMD , C.SMSTR_CHRT_ATNDC_RCG_SYMD AS SBJCT_ATNDC_RCG_SYMD , C.SMSTR_CHRT_ATNDC_RCG_EYMD AS SBJCT_ATNDC_RCG_EYMD , CAST(NULL AS VARCHAR2(30)) AS RGTR_ID , CAST(NULL AS VARCHAR2(14)) AS REG_DTTM , CAST(NULL AS VARCHAR2(30)) AS MDFR_ID , CAST(NULL AS VARCHAR2(14)) AS MOD_DTTM , C.SCHDL_WKNONM AS SBJCT_SCHDL_WKNONM FROM TB_LMS_SBJCT A INNER JOIN TB_LMS_SMSTR_CHRT B ON B.SMSTR_CHRT_ID = A.SMSTR_CHRT_ID INNER JOIN TB_LMS_SMSTR_CHRT_SCHDL C ON C.SMSTR_CHRT_ID = A.SMSTR_CHRT_ID WHERE A.SBJCT_ID = #{sbjctId} AND A.DELYN = 'N'
AND B.ORG_ID = #{orgId}
AND NOT EXISTS ( SELECT 1 FROM TB_LMS_SBJCT_SCHDL S WHERE S.SBJCT_ID = A.SBJCT_ID ) ) ORDER BY TOC_SEQNO, SBJCT_SCHDL_WKNO

mapper.insert:
/*
    SQL ID : SbjctDAO.insertSbjctOfring
    설  명 : 과목개설 등록
*/
INSERT INTO TB_LMS_SBJCT (
    SBJCT_ID
  , SBJCT_REF_TYCD
  , SMSTR_CHRT_ID
  , SBJCT_GBNCD
  , CRS_GBNCD
  , SBJCT_TYCD
  , SBJCTNM
  , SBJCT_EXPLN
  , SBJCT_ENNM
  , SBJCT_YR
  , SBJCT_SMSTR
  , CRDTS
  , RVW_PSBL_GBNCD
  , RVW_SDTTM
  , RVW_EDTTM
  , DVCLAS_NO
  , DVCLAS_NCKNM
  , DEPT_ID
  , CMCRS_GBNCD
  , LRN_CNTRL_GBNCD
  , SBJCT_LCTR_SDTTM
  , SBJCT_LCTR_EDTTM
  , ATNDLC_APLY_MTHD_CD
  , ATNDLC_QUOTA
  , ATNDLC_CERT_STSCD
  , ATNDLC_APLY_SDTTM
  , ATNDLC_APLY_EDTTM
  , AUDIT_SDTTM
  , AUDIT_EDTTM
  , SBJCT_LATE_RECG_DTTM
  , MRK_PROC_SDTTM
  , MRK_PROC_EDTTM
  , USEYN
  , DELYN
  , LCTR_FRMT_GBNCD
  , RGTR_ID
  , REG_DTTM
  , LCTR_GBNCD
  , CRCLMN_NO
  , LCTR_EVLYN
  , LCTR_PRVW_WKNO
  , EVL_GBNCD
  , PASSFAIL_SCR
) VALUES (
    #{sbjctId}
  , #{sbjctRefTycd}
  , #{smstrChrtId}
  , #{sbjctGbncd}
  , #{crsGbncd}
  , #{sbjctTycd}
  , #{sbjctnm}
  , #{sbjctExpln}
  , #{sbjctEnnm}
  , #{sbjctYr}
  , #{sbjctSmstr}
  , #{crdts}
  , #{rvwPsblGbncd}
  , #{rvwSdttm}
  , #{rvwEdttm}
  , #{dvclasNo}
  , #{dvclasNcknm}
  , #{cmcrsGbncd}
  , #{lrnCntrlGbncd}
  , #{sbjctLctrSdttm}
  , #{sbjctLctrEdttm}
  , #{atndlcAplyMthdCd}
  , #{atndlcQuota}
  , #{atndlcCertStscd}
  , #{atndlcAplySdttm}
  , #{atndlcAplyEdttm}
  , #{auditSdttm}
  , #{auditEdttm}
  , #{sbjctLateRecgDttm}
  , #{mrkProcSdttm}
  , #{mrkProcEdttm}
  , #{useyn}
  , #{delyn}
  , #{lctrFrmtGbncd}
  , #{rgtrId}
  , FN_DTTM()
  , #{lctrGbncd}
  , #{sbjctCd}
  , #{lctrEvlyn}
  , #{lctrPrvwWkno}
  , #{evlGbncd}
  , #{passfailScr}
)

mapper.update:
/*
    SQL ID : SbjctDAO.updateSbjctOfring
    설  명 : 과목개설 수정
*/
UPDATE TB_LMS_SBJCT
SET
    SBJCT_REF_TYCD = #{sbjctRefTycd}
  , SMSTR_CHRT_ID = #{smstrChrtId}
  , CRS_GBNCD = #{crsGbncd}
  , SBJCT_TYCD = #{sbjctTycd}
  , SBJCTNM = #{sbjctnm}
  , SBJCT_EXPLN = #{sbjctExpln}
  , SBJCT_ENNM = #{sbjctEnnm}
  , SBJCT_YR = #{sbjctYr}
  , SBJCT_SMSTR = #{sbjctSmstr}
  , CRDTS = #{crdts}
  , RVW_PSBL_GBNCD = #{rvwPsblGbncd}
  , RVW_SDTTM = #{rvwSdttm}
  , RVW_EDTTM = #{rvwEdttm}
  , DVCLAS_NO = #{dvclasNo}
  , DVCLAS_NCKNM = #{dvclasNcknm}
  , CMCRS_GBNCD = #{cmcrsGbncd}
  , LRN_CNTRL_GBNCD = #{lrnCntrlGbncd}
  , SBJCT_LCTR_SDTTM = #{sbjctLctrSdttm}
  , SBJCT_LCTR_EDTTM = #{sbjctLctrEdttm}
  , ATNDLC_APLY_MTHD_CD = #{atndlcAplyMthdCd}
  , ATNDLC_QUOTA = #{atndlcQuota}
  , ATNDLC_CERT_STSCD = #{atndlcCertStscd}
  , ATNDLC_APLY_SDTTM = #{atndlcAplySdttm}
  , ATNDLC_APLY_EDTTM = #{atndlcAplyEdttm}
  , AUDIT_EDTTM = #{auditEdttm}
  , SBJCT_LATE_RECG_DTTM = #{sbjctLateRecgDttm}
  , MRK_PROC_SDTTM = #{mrkProcSdttm}
  , MRK_PROC_EDTTM = #{mrkProcEdttm}
  , USEYN = #{useyn}
  , LCTR_FRMT_GBNCD = #{lctrFrmtGbncd}
  , MDFR_ID = #{mdfrId}
  , MOD_DTTM = TO_CHAR(SYSDATE, 'YYYYMMDDHH24MISS')
  , LCTR_GBNCD = #{lctrGbncd}
  , CRCLMN_NO = #{sbjctCd}
  , LCTR_EVLYN = #{lctrEvlyn}
  , LCTR_PRVW_WKNO = #{lctrPrvwWkno}
  , EVL_GBNCD = #{evlGbncd}
  , PASSFAIL_SCR = #{passfailScr}
WHERE SBJCT_ID = #{sbjctId}
  AND DELYN = 'N'

/*
    SQL ID : SbjctDAO.updateSbjctOfringUseyn
    설  명 : 과목개설 목록에서 사용여부만 수정
*/
UPDATE TB_LMS_SBJCT
   SET USEYN = #{useyn}
     , MDFR_ID = #{mdfrId}
     , MOD_DTTM = FN_DTTM()
 WHERE SBJCT_ID = #{sbjctId}
   AND NVL(SBJCT_TYCD, ' ') != 'OPEN_LCTR_SYSTEM'
   AND DELYN = 'N'

/*
    SQL ID : SbjctDAO.updateOpenLctrOfringUseyn
    설  명 : 공개강좌개설 목록에서 사용여부만 수정
*/
UPDATE TB_LMS_SBJCT
   SET USEYN = #{useyn}
     , MDFR_ID = #{mdfrId}
     , MOD_DTTM = FN_DTTM()
 WHERE SBJCT_ID = #{sbjctId}
   /* 과목개설 일반 데이터가 목록 토글로 수정되지 않도록 공개강좌 유형으로 제한한다. */
   AND SBJCT_TYCD = 'OPEN_LCTR_SYSTEM'
   AND DELYN = 'N'

mapper.insert:
/* SQL ID : SbjctDAO.insertSbjctOfringSchdlList 설 명 : 과목개설 주차 기간 설정 목록 벌크 등록 */ INSERT INTO TB_LMS_SBJCT_SCHDL ( SBJCT_SCHDL_ID , SBJCT_ID , SMSTR_CHRT_SCHDL_ID , SBJCT_SCHDL_WKNO , TOC_SEQNO , SBJCT_SYMD , SBJCT_EYMD , SBJCT_ATNDC_RCG_SYMD , SBJCT_ATNDC_RCG_EYMD , RGTR_ID , REG_DTTM , MDFR_ID , MOD_DTTM , SBJCT_SCHDL_WKNONM ) SELECT SRC.SBJCT_SCHDL_ID , SRC.SBJCT_ID , SRC.SMSTR_CHRT_SCHDL_ID , SRC.SBJCT_SCHDL_WKNO , SRC.TOC_SEQNO , SRC.SBJCT_SYMD , SRC.SBJCT_EYMD , SRC.SBJCT_ATNDC_RCG_SYMD , SRC.SBJCT_ATNDC_RCG_EYMD , SRC.RGTR_ID , TO_CHAR(SYSDATE, 'YYYYMMDDHH24MISS') , SRC.MDFR_ID , TO_CHAR(SYSDATE, 'YYYYMMDDHH24MISS') , SRC.SBJCT_SCHDL_WKNONM FROM (
SELECT #{item.sbjctSchdlId, jdbcType=VARCHAR} AS SBJCT_SCHDL_ID , #{item.sbjctId, jdbcType=VARCHAR} AS SBJCT_ID , #{item.smstrChrtSchdlId, jdbcType=VARCHAR} AS SMSTR_CHRT_SCHDL_ID , #{item.sbjctSchdlWkno, jdbcType=NUMERIC} AS SBJCT_SCHDL_WKNO , #{item.tocSeqno, jdbcType=NUMERIC} AS TOC_SEQNO , #{item.sbjctSymd, jdbcType=VARCHAR} AS SBJCT_SYMD , #{item.sbjctEymd, jdbcType=VARCHAR} AS SBJCT_EYMD , #{item.sbjctAtndcRcgSymd, jdbcType=VARCHAR} AS SBJCT_ATNDC_RCG_SYMD , #{item.sbjctAtndcRcgEymd, jdbcType=VARCHAR} AS SBJCT_ATNDC_RCG_EYMD , #{item.rgtrId, jdbcType=VARCHAR} AS RGTR_ID , #{item.mdfrId, jdbcType=VARCHAR} AS MDFR_ID , #{item.sbjctSchdlWknonm, jdbcType=VARCHAR} AS SBJCT_SCHDL_WKNONM FROM DUAL
) SRC INNER JOIN TB_LMS_SBJCT A ON A.SBJCT_ID = SRC.SBJCT_ID AND A.DELYN = 'N'

mapper.delete:
/*
    SQL ID : SbjctDAO.deleteSbjctOfringSchdlList
    설  명 : 과목개설 주차 기간 설정 목록 삭제
*/
DELETE FROM TB_LMS_SBJCT_SCHDL
WHERE SBJCT_ID = #{sbjctId}

/*
    SQL ID : SbjctDAO.deleteSbjctOfringAdmList
    설  명 : 과목개설 과목관리자 목록 삭제
*/
DELETE FROM TB_LMS_SBJCT_ADM
WHERE SBJCT_ID = #{sbjctId}

mapper.insert:
/* SQL ID : SbjctDAO.insertSbjctOfringAdmList 설 명 : 과목개설 과목관리자 벌크 등록 */ INSERT INTO TB_LMS_SBJCT_ADM ( SBJCT_ADM_ID , SBJCT_ID , USER_ID , SBJCT_ADM_TYCD , RGTR_ID , REG_DTTM , MDFR_ID , MOD_DTTM , SBJCT_ADM_SEQNO ) SELECT SRC.SBJCT_ADM_ID , SRC.SBJCT_ID , SRC.USER_ID , SRC.SBJCT_ADM_TYCD , SRC.RGTR_ID , FN_DTTM() , SRC.MDFR_ID , FN_DTTM() , SRC.SBJCT_ADM_SEQNO FROM (
SELECT #{item.sbjctAdmId} AS SBJCT_ADM_ID , #{item.sbjctId} AS SBJCT_ID , #{item.userId} AS USER_ID , #{item.sbjctAdmTycd} AS SBJCT_ADM_TYCD , #{item.rgtrId} AS RGTR_ID , #{item.mdfrId} AS MDFR_ID , #{item.sbjctAdmSeqno} AS SBJCT_ADM_SEQNO FROM DUAL
) SRC INNER JOIN TB_LMS_SBJCT CUR ON CUR.SBJCT_ID = SRC.SBJCT_ID AND CUR.DELYN = 'N' INNER JOIN TB_LMS_USER U ON U.USER_ID = SRC.USER_ID AND U.USER_TYCD IN ('PROF', 'COPROF', 'TUT', 'ASSI')

mapper.update:
/*
    SQL ID : SbjctDAO.updateSbjctOfringProfId
    설  명 : 과목개설 대표 교수아이디 수정
*/
UPDATE TB_LMS_SBJCT
SET
    PROF_ID = #{userId}
  , MDFR_ID = #{mdfrId}
  , MOD_DTTM = TO_CHAR(SYSDATE, 'YYYYMMDDHH24MISS')
WHERE SBJCT_ID = #{sbjctId}
  AND DELYN = 'N'

mapper.select:
/* SQL ID : SbjctDAO.admSbjctOfringStdntExcelList 설 명 : 과목개설 수강생 엑셀 업로드 학생 목록 조회 */ SELECT U.USER_ID , U.USERNM , U.STDNT_NO , (SELECT MAX(UC.CNTCT) FROM TB_LMS_USER_CNTCT UC WHERE UC.USER_ID = U.USER_ID AND UC.CNTCT_TYCD = 'MBL_PHN') AS MBL_PHN , (SELECT MAX(UC.CNTCT) FROM TB_LMS_USER_CNTCT UC WHERE UC.USER_ID = U.USER_ID AND UC.CNTCT_TYCD = 'INDV_EML') AS EML FROM TB_LMS_USER U WHERE U.USER_TYCD = 'STDNT' AND U.STDNT_NO IN
#{item.stdntNo}
ORDER BY U.USERNM, U.STDNT_NO, U.USER_ID

mapper.insert:
/* SQL ID : SbjctDAO.insertSbjctOfringStdntList 설 명 : 과목개설 수강생 목록 벌크 등록 */ INSERT INTO TB_LMS_ATNDLC ( ATNDLC_ID , SBJCT_ID , USER_ID , DEPT_ID , STDNT_NO , RPTYN , ATNDLC_APLY_DTTM , ATNDLC_CERT_DTTM , AUDITYN , RGTR_ID , REG_DTTM , MDFR_ID , MOD_DTTM , ATNDLC_STSCD ) SELECT SRC.ATNDLC_ID , SRC.SBJCT_ID , SRC.USER_ID , NVL(U.DEPT_ID, '') , NVL(U.STDNT_NO, '') , SRC.RPTYN , FN_DTTM() , FN_DTTM() , 'N' , SRC.RGTR_ID , FN_DTTM() , SRC.MDFR_ID , FN_DTTM() , SRC.ATNDLC_STSCD FROM (
SELECT #{item.atndlcId} AS ATNDLC_ID , #{item.sbjctId} AS SBJCT_ID , #{item.userId} AS USER_ID , #{item.rptyn} AS RPTYN , #{item.rgtrId} AS RGTR_ID , #{item.mdfrId} AS MDFR_ID , #{item.atndlcStscd} AS ATNDLC_STSCD FROM DUAL
) SRC INNER JOIN TB_LMS_USER U ON U.USER_ID = SRC.USER_ID AND U.USER_TYCD = 'STDNT'

mapper.select:
/* SQL ID : SbjctDAO.admSbjctList 설 명 : 과목 목록 조회 */ SELECT SBJ.SBJCT_ID , SBJ.SBJCTNM FROM TB_LMS_SBJCT SBJ JOIN TB_LMS_SMSTR_CHRT SMSTR ON SBJ.SMSTR_CHRT_ID = SMSTR.SMSTR_CHRT_ID WHERE 1=1
AND SMSTR.ORG_ID = #{orgId}
AND SMSTR.DGRS_YR = #{dgrsYr}
AND SMSTR.DGRS_SMSTR_CHRT = #{dgrsSmstrChrt}
AND SBJ.USEYN = 'Y' AND SBJ.DELYN = 'N' ORDER BY SBJ.SBJCTNM ASC

/*
    SQL ID : SbjctDAO.profSbjctList
    설  명 : 과목 목록 조회
*/
SELECT SBJ.SBJCT_ID, SBJ.SBJCTNM
FROM TB_LMS_SBJCT_ADM PRF
JOIN TB_LMS_SBJCT SBJ ON PRF.SBJCT_ID = SBJ.SBJCT_ID
JOIN TB_LMS_SMSTR_CHRT SMSTR ON SBJ.SMSTR_CHRT_ID = SMSTR.SMSTR_CHRT_ID
WHERE 1=1
AND PRF.USER_ID = #{rprsId}


    AND SMSTR.ORG_ID = #{orgId}


    AND SMSTR.DGRS_YR = #{dgrsYr}


    AND SMSTR.DGRS_SMSTR_CHRT = #{dgrsSmstrChrt}

  AND SBJ.USEYN = 'Y'
  AND SBJ.DELYN = 'N'
ORDER BY SBJ.SBJCTNM ASC

/*
    SQL ID : SbjctDAO.stdntSbjctList
    설  명 : 과목 목록 조회
*/
SELECT SBJ.SBJCT_ID, SBJ.SBJCTNM
FROM TB_LMS_ATNDLC STD
JOIN TB_LMS_SBJCT SBJ ON STD.SBJCT_ID = SBJ.SBJCT_ID
JOIN TB_LMS_SMSTR_CHRT SMSTR ON SBJ.SMSTR_CHRT_ID = SMSTR.SMSTR_CHRT_ID
WHERE 1=1
  AND STD.USER_ID IN (
    SELECT USER_ID
    FROM TB_LMS_USER X
    WHERE X.USER_RPRS_ID = #{rprsId}
)

    AND SMSTR.ORG_ID = #{orgId}


    AND SMSTR.DGRS_YR = #{dgrsYr}


    AND SMSTR.DGRS_SMSTR_CHRT = #{dgrsSmstrChrt}

AND SBJ.USEYN = 'Y'
AND SBJ.DELYN = 'N'
ORDER BY SBJ.SBJCTNM ASC
